$wrapper='E:\NEXUS-QA\rdc-l1-task-preflight-20261014T062235Z\invoke_nexus_rdc_l1_preflight.ps1'
$probe='E:\NEXUS-QA\rdc-l1-task-preflight-20261014T062235Z\probe_nexus_rdc_l1_preflight.py'
